INSERT INTO `comments` (`id`, `thesis_submission_id`, `user_id`, `parent_id`, `content`, `created_at`, `updated_at`, `deleted_at`) VALUES ('1', '1', '2', NULL, 'Di Latar belakang isinya tidak boleh diambil dari Jurnal semua, perlu dijabarkan permasalahan dari hasil wawancara atau observasi.- Data pendukung: perlu ditambahkan data kuantitatif tentang jumlah sarana prasarana yang dikelola UVERS (misalnya jumlah kelas, proyektor, AC), agar urgensi penelitian lebih terasa.- Rumusan masalah dan tujuan: masih cenderung umum, bisa dibuat lebih spesifik, misalnya “Bagaimana sistem dapat menghasilkan laporan otomatis kondisi fasilitas?” atau “Bagaimana sistem memberikan notifikasi jadwal maintenance?”.- Ruang lingkup sistem: sudah ada batasan fitur, tetapi sebaiknya dijelaskan lebih rinci fitur utama (dashboard monitoring, riwayat maintenance, notifikasi).-Dampak yang diuraikan sudah baik. Untuk memperkuat, proposal bisa menambahkan estimasi kuantitatif, misalnya \"Diharapkan dapat mengurangi waktu pelaporan dari beberapa jam menjadi beberapa menit\" atau \"Meningkatkan akurasi data inventaris aset hingga 99%\".', '2026-07-16 09:18:47', '2026-07-16 09:18:47', NULL);
INSERT INTO `comments` (`id`, `thesis_submission_id`, `user_id`, `parent_id`, `content`, `created_at`, `updated_at`, `deleted_at`) VALUES ('2', '3', '2', NULL, 'Identifikasi Permasalahan 1. Tidak efisien pada pembuatan dokumen spreadsheet untuk penilaian setiap judul yang diajukan Mahasiswa 2. Sulit dalam melakukan peniliaian 3. Keamanan data karena data dapat diakses oleh user lain. 4. Data tidak terpusat mempersulit dalam memberikan informasi kepada mahasiswa.- Pastikan bahwa penerapan metodologi Agile Scrum dapat menjawab kebutuhan pengembangan yang fleksibel dan iteratif, serta memberikan cukup ruang untuk perubahan sesuai umpan balik dari pemangku kepentingan.- Apakah dampak dari inefisiensi ini cukup signifikan? Dapatkah contoh konkret diberikan, seperti waktu yang terbuang atau masalah dalam pencatatan dan pelacakan data yang pernah terjadi?', '2026-07-16 09:18:47', '2026-07-16 09:18:47', NULL);
INSERT INTO `comments` (`id`, `thesis_submission_id`, `user_id`, `parent_id`, `content`, `created_at`, `updated_at`, `deleted_at`) VALUES ('3', '5', '2', NULL, 'Harus lebih jelas algoritma yang digunakan untuk dapat merekomendasikan konsumsi gula harian pengguna.- Validasi Sistem: perlu dijelaskan bagaimana sistem grading akan diuji (misalnya, mengacu pada standar WHO atau Kemenkes tentang asupan gula).- Ruang Lingkup: tambahkan batasan agar tidak melebar, misalnya hanya fokus pada minuman kemasan populer di Indonesia. Jelaskan dasar atau acuan untuk algoritma grading-nya (misal: \"diadaptasi dari standar Kemenkes RI atau standar WHO\").', '2026-07-16 09:18:48', '2026-07-16 09:18:48', NULL);
INSERT INTO `comments` (`id`, `thesis_submission_id`, `user_id`, `parent_id`, `content`, `created_at`, `updated_at`, `deleted_at`) VALUES ('4', '6', '2', NULL, '1. Detailkan Metode Evaluasi: Pada tahap Beta Testing, jelaskan secara spesifik bagaimana efektivitas edukatif akan diukur. Sangat disarankan untuk menggunakan metode pre-test dan post-test kepada siswa untuk mendapatkan data kuantitatif tentang peningkatan pemahaman mereka setelah bermain game.  2. Jelaskan Konsep Game: Untuk memberikan gambaran lebih jelas, bisa ditambahkan satu atau dua kalimat pada bagian Inisiasi  mengenai genre atau konsep inti game (misalnya: puzzle, kuis, petualangan, dll).', '2026-07-16 09:18:48', '2026-07-16 09:18:48', NULL);
INSERT INTO `comments` (`id`, `thesis_submission_id`, `user_id`, `parent_id`, `content`, `created_at`, `updated_at`, `deleted_at`) VALUES ('5', '7', '2', NULL, 'Rekomendasi harus menggunakan algoritma yang tepat agar sesuai dengan profil pengguna- Ruang Lingkup: masih umum, sebaiknya lebih detail fitur yang akan dikembangkan (misalnya: integrasi GPS, sistem rekomendasi berbasis preferensi, informasi budaya lokal).- Evaluasi Aplikasi: perlu dijelaskan bagaimana efektivitas aplikasi akan diuji (misalnya melalui usability testing, SUS score, atau uji kepuasan pengguna).- Integrasi Budaya Lokal: karena pemandu wisata juga berfungsi sebagai mediator budaya, sebaiknya dijelaskan apakah aplikasi akan mencakup informasi etika, budaya, dan bahasa lokal.- Inovasi Teknis: agar berbeda dari aplikasi peta biasa (Google Maps), perlu ditonjolkan fitur pembeda, misalnya rekomendasi otomatis berbasis machine learning, AR untuk navigasi, atau chatbot interaktif. Sebutkan Teknologi: Cantumkan technology stack yang jelas. Contoh: \"Aplikasi akan dikembangkan secara native untuk Android menggunakan Kotlin, memanfaatkan Google Maps API untuk fitur lokasi, dan Firebase sebagai backend.\". Serta Jelaskan Konsep Rekomendasi: Beri gambaran awal tentang cara kerja sistem rekomendasi (misalnya, berbasis popularitas, berbasis kategori preferensi pengguna, dll).', '2026-07-16 09:18:48', '2026-07-16 09:18:48', NULL);
INSERT INTO `comments` (`id`, `thesis_submission_id`, `user_id`, `parent_id`, `content`, `created_at`, `updated_at`, `deleted_at`) VALUES ('6', '8', '2', NULL, 'Penulisan rumusan masalah harus mencakup semua yang ada pada identifikasi masalah Pertimbangkan Metodologi Agile: Disarankan untuk mempertimbangkan metode Agile. Mengingat pengguna sistem (admin dan teknisi) dapat memberikan feedback yang berharga selama pengembangan, pendekatan iteratif Agile akan lebih efektif dalam memastikan sistem benar-benar sesuai dengan kebutuhan alur kerja mereka dibandingkan Waterfall.', '2026-07-16 09:18:48', '2026-07-16 09:18:48', NULL);
INSERT INTO `comments` (`id`, `thesis_submission_id`, `user_id`, `parent_id`, `content`, `created_at`, `updated_at`, `deleted_at`) VALUES ('7', '10', '2', NULL, 'Harus melakukan wawancara atau observasi terhadap stakeholder kemahasiswaan untuk mendapatkan data yang lengkap - Tambahkan Metodenya.- Sebutkan Teknologi: Proposal harus mencantumkan technology stack yang akan dipakai. Contoh: \"Aplikasi akan dibangun dengan Kotlin untuk Android, dan menggunakan Firebase sebagai backend untuk notifikasi real-time.', '2026-07-16 09:18:49', '2026-07-16 09:18:49', NULL);
INSERT INTO `comments` (`id`, `thesis_submission_id`, `user_id`, `parent_id`, `content`, `created_at`, `updated_at`, `deleted_at`) VALUES ('8', '11', '2', NULL, 'Harus jelas objek penelitian dilakukan dimana- Permasalahan penelitian tidak jelas dan didapat dari mana Secara keseluruhan Isi Proposal harus di pertajam lagi. Mahasiswa harus menetapkan sebuah studi kasus yang nyata, yang masih menggunakan pencatatan manual dan bersedia menjadi objek penelitian. Selanjutnya, menjelaskan secara spesifik bagaimana sistem ini akan memberikan dampak positif bagi perusahaan atau organisasi tersebut. Bagaimana sistem akan dirancang, dibangun, dan diuji. Urgensi harus dikaitkan langsung dengan studi kasus. Setelah studi kasus ditemukan, jelaskan masalah mendesak apa yang sedang mereka hadapi akibat sistem manual (misalnya, sering kehilangan barang, kesulitan audit, dll). Proposal ini harus direvisi secara fundamental dan menyeluruh. Mahasiswa harus melengkapi semua bagian yang hilang, terutama bab metodologi pengembangan perangkat lunak, dan mengaitkan seluruh isi proposal dengan sebuah studi kasus yang konkret.', '2026-07-16 09:18:49', '2026-07-16 09:18:49', NULL);
INSERT INTO `comments` (`id`, `thesis_submission_id`, `user_id`, `parent_id`, `content`, `created_at`, `updated_at`, `deleted_at`) VALUES ('9', '12', '2', NULL, 'Disarankan untuk fokus pada satu jenjang pendidikan (misalnya, siswa SMP) dan satu mata pelajaran (misalnya, Sejarah atau Biologi). Hal ini akan membuat proyek lebih terarah, dapat dicapai, dan hasil pengujiannya lebih bermakna.', '2026-07-16 09:18:49', '2026-07-16 09:18:49', NULL);
INSERT INTO `comments` (`id`, `thesis_submission_id`, `user_id`, `parent_id`, `content`, `created_at`, `updated_at`, `deleted_at`) VALUES ('10', '15', '2', NULL, 'Spesifikasikan Target Pengujian: Jelaskan target pengguna untuk uji coba (misalnya, siswa SMP atau SMA) agar lebih fokus. Sebutkan Teknologi: Proposal ini belum menyebutkan technology stack. Tambahkan detail teknologi yang akan digunakan (misalnya PHP Laravel, MySQL) untuk melengkapi perencanaan. Hilangkan kontradiksi platform. Pilih satu platform target (Android atau Windows) dan pastikan seluruh dokumen konsisten.', '2026-07-16 09:18:50', '2026-07-16 09:18:50', NULL);
